/** Doll artwork (generated by the asset build script; do not edit by hand). */
export const EXPRESSIONS = ["normal", "squish", "sleep", "worried", "happy", "think"] as const;
export type Expression = (typeof EXPRESSIONS)[number];

export interface PoseArt {
  /** Pixel size of the images (all expressions of a pose share it). */
  width: number;
  height: number;
  /** CSS clip-path enclosing the drawing; also limits where she can be grabbed. */
  hull: string;
  /** Where the "zzz" floats while she sleeps, as fractions of the image box. */
  head: { x: number; y: number };
  /** Missing expressions fall back to "normal". */
  images: Record<Expression, string>;
}

